<div class="page-header"><div><a class="text-link small muted" href="<?= e(route_url('/portfolio')) ?>" style="margin-bottom:13px"><?= icon('arrow-left',14) ?> My portfolio</a><h1><?= $project?'Keep building your story.':'Something you made. Something to share.' ?></h1><p>A clear explanation is part of a good project. Tell us what you built and what you learned.</p></div><?php if($project): ?><div class="page-actions"><?= badge($project['visibility']) ?></div><?php endif; ?></div>
<div class="two-column"><div class="stack"><section class="card form-card"><form action="<?= e(route_url('/api/projects/' . ($project?(int)$project['id']:'new'))) ?>" method="post" enctype="multipart/form-data" data-api><?= csrfField() ?><div class="field"><label for="title">Project title</label><input id="title" name="title" value="<?= e($project['title']??'') ?>" required minlength="3" maxlength="160" placeholder="Give your next chapter a name"></div><div class="field"><label for="description">Your project story</label><textarea id="description" name="description" required minlength="10" maxlength="12000" placeholder="The idea, your approach, what you learned and what you’d do next…" style="min-height:220px"><?= e($project['description']??'') ?></textarea></div><div class="field"><label for="skills">Skills you practised <span>· separate with commas</span></label><input id="skills" name="skills" maxlength="700" value="<?= e($skills) ?>" placeholder="Semantic HTML, responsive CSS, accessibility"></div><div class="form-grid"><div class="field"><label for="project-url">Live project URL</label><input id="project-url" name="project_url" type="url" value="<?= e($project['project_url']??'') ?>" maxlength="2000" placeholder="https://…"></div><div class="field"><label for="repository-url">Source-code repository</label><input id="repository-url" name="repository_url" type="url" value="<?= e($project['repository_url']??'') ?>" maxlength="2000" placeholder="https://…"></div><div class="field"><label for="path-id">Related learning path</label><select id="path-id" name="path_id"><option value="">An independent project</option><?php foreach($paths as $p): ?><option value="<?= (int)$p['id'] ?>" <?= (int)($project['path_id']??0)===(int)$p['id']?'selected':'' ?>><?= e($p['title']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="completed-on">Completion date <span>· optional</span></label><input id="completed-on" name="completed_on" type="date" value="<?= e($project['completed_on']??'') ?>"></div><div class="field full"><label for="visibility">Who can see your project?</label><select id="visibility" name="visibility"><option value="private" <?= ($project['visibility']??'private')==='private'?'selected':'' ?>>Just me · private</option><option value="public" <?= ($project['visibility']??'')==='public'?'selected':'' ?>>Anyone with the link · public</option></select><span class="field-help">Public projects can appear in the community and be viewed without signing in.</span></div></div><div class="separator"></div><div class="upload-zone"><?= icon('upload',25) ?><p>A little visual context</p><small>Add a screenshot · JPG or PNG · up to 5 MB · maximum 5 per project</small><input type="file" name="image" accept=".jpg,.jpeg,.png" aria-label="Project screenshot"></div><?php if($images): ?><div class="project-images" style="margin-top:20px"><?php foreach($images as $image): ?><img src="<?= e(route_url('/media/' . ((int)$image['id']))) ?>" alt="<?= e($image['file_name']) ?>" loading="lazy"><?php endforeach; ?></div><?php endif; ?><div class="form-actions"><a class="btn btn-ghost" href="<?= e(route_url('/portfolio')) ?>">Back to my portfolio</a><button class="btn btn-primary">Save my project <?= icon('check',16) ?></button></div></form></section>
<?php if($reviews): ?><section class="card card-pad"><div class="card-header"><h2>A few fresh perspectives.</h2><?= icon('message',19) ?></div><?php foreach($reviews as $review): ?><article class="feedback-card"><h4><span><?= (int)setting('peer_review_anonymous',0)?'A fellow learner':e($review['full_name']) ?></span><span class="badge badge-neutral">Peer feedback</span></h4><p class="fine-print">Reviewed snapshot: <?= e($review['snapshot_title']) ?> · Feedback does not imply assignment approval.</p><?php foreach(\Learnow\Repositories\DB::all('SELECT r.*,q.prompt,q.max_score FROM peer_review_responses r JOIN peer_review_questions q ON q.id=r.question_id WHERE r.review_id=?',[$review['id']]) as $response): ?><p><strong><?= e($response['prompt']) ?> · <?= (int)$response['score'] ?>/<?= (int)$response['max_score'] ?></strong><br><?= e($response['feedback']) ?></p><?php endforeach; ?></article><?php endforeach; ?></section><?php endif; ?></div>
<aside class="stack"><section class="card card-pad"><span class="icon-tile green" style="margin-bottom:17px"><?= icon('lightbulb',24) ?></span><h2 style="font-size:19px;margin-bottom:12px">Tell the useful story.</h2><ul class="objective-list" style="margin-top:22px"><?php foreach(['What problem were you exploring?','What did you build, and why?','What did you test or learn?','What would you improve next?'] as $s): ?><li><?= icon('check',15) ?><span><?= e($s) ?></span></li><?php endforeach; ?></ul><p class="fine-print">Only share original work or material you have permission to use. Remove secrets and private information first.</p></section><?php if($project): ?><section class="card card-pad"><div class="card-header"><h2>A little outside perspective.</h2></div><p class="fine-print">Requesting feedback shares a text-and-link snapshot of this project with up to <?= (int)setting('peer_review_count',2) ?> eligible learners, even if the project is private. Images stay private unless you publish the project. Feedback is not official approval.</p><form action="<?= e(route_url('/api/projects/' . ((int)$project['id']) . '/reviews')) ?>" method="post" data-api data-confirm="Share a snapshot of this project’s text and links with assigned eligible peer reviewers? This does not publish your private project to everyone." style="margin-top:18px"><?= csrfField() ?><button class="btn btn-secondary btn-small btn-block">Ask for constructive feedback <?= icon('message',15) ?></button></form></section><?php if($project['visibility']==='public'): ?><section class="card card-pad"><div class="card-header"><h2>Worth sharing.</h2></div><a href="<?= e(route_url('/projects/' . ($project['slug']))) ?>" class="btn btn-secondary btn-small btn-block" target="_blank" rel="noopener">Open public project <?= icon('arrow-up-right',15) ?></a></section><?php endif; ?><form action="<?= e(route_url('/api/projects/' . ((int)$project['id']) . '/delete')) ?>" method="post" data-api data-confirm="Remove this project and its attached images and peer reviews? This cannot be undone."><?= csrfField() ?><button class="btn btn-danger btn-small btn-block"><?= icon('trash',15) ?> Remove this project</button></form><?php endif; ?></aside></div>
